{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The private ACL alone does not prevent future bucket policies or ACL changes from exposing the bucket. No account-level protection is declared in this file."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Public bucket policies are not restricted",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enable restrict_public_buckets, allowing a future public bucket policy to expose its contents."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is not enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "Without versioning, objects overwritten or deleted accidentally or maliciously cannot be recovered from prior versions."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"b\" {\n  bucket = \"my-tf-test-bucket-ggff\"\n  acl    = \"private\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"b\" {\n  bucket = aws_s3_bucket.b.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_versioning\" \"b\" {\n  bucket = aws_s3_bucket.b.id\n\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n",
  "fix_summary": "Added a complete S3 Public Access Block to prevent exposure through ACLs or bucket policies. Enabled bucket versioning to support recovery from unintended overwrites and deletions."
}
